code:
.fill {
  height: 100dvh !important;
  min-height: 0 !important;
  border: 0 !important;
  border-radius: 0 !important;
}
.workspace {
  height: 760px !important;
}
.headerTitle {
  font-size: 20px;
  line-height: 28px;
  font-weight: 600;
}
.main {
  min-width: 0;
  padding: 12px;
}
.toolbar {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
  padding: 8px 0;
  width: 100%;
  min-width: 0;
}
.toolbar > div {
  border: 0;
  padding: 0;
}
.search {
  width: 180px;
  max-width: 100%;
}
.connection,
.properties {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
}
.connection {
  border-bottom: 1px solid var(--border);
  padding-bottom: 12px;
  margin-bottom: 12px;
  font-size: 12px;
  color: var(--text-secondary);
}
.connection > :last-child {
  margin-left: auto;
}
.properties {
  font-size: 12px;
  color: var(--text-secondary);
}
.stage {
  display: flex;
  flex-direction: column;
  gap: 4px;
  font-size: 12px;
  overflow-wrap: anywhere;
}
.card {
  border: 1px solid var(--border);
  border-radius: 8px;
  background: var(--surface);
  overflow: hidden;
}
.card[data-selected="true"] {
  border-color: var(--primary);
  background: var(--selection);
}
.cardMain {
  width: 100%;
  display: flex;
  flex-direction: column;
  align-items: stretch;
  gap: 8px;
  text-align: left;
  padding: 12px;
}
button.cardMain {
  cursor: pointer;
}
button.cardMain:hover {
  background: var(--surface-hover);
}
button.cardMain:focus-visible {
  outline: 2px solid var(--ring);
  outline-offset: -4px;
}
.runTitle {
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
  font-size: 14px;
  font-weight: 500;
  overflow-wrap: anywhere;
}
.meta {
  font-size: 12px;
  color: var(--text-secondary);
  overflow-wrap: anywhere;
}
.warning {
  color: var(--status-waiting);
  overflow-wrap: anywhere;
}
.row {
  border-bottom: 1px solid var(--border);
  min-width: 0;
}
.row > div {
  flex-wrap: wrap;
}
.row .properties {
  margin: 4px 0;
}
.groupTitle {
  padding: 12px 8px;
  border-bottom: 1px solid var(--border);
  font-size: 14px;
  font-weight: 500;
  background: var(--surface-raised);
}
.section,
.request {
  padding: 12px 0;
  min-width: 0;
  overflow-wrap: anywhere;
}
.section h2 {
  font-size: 16px;
  font-weight: 500;
}
.request {
  border-top: 1px solid var(--border);
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.request h3 {
  font-size: 14px;
  font-weight: 500;
}
.actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  padding: 8px 0;
}
.notice {
  padding: 8px 12px;
  margin-bottom: 8px;
  border-left: 2px solid var(--status-waiting);
  font-size: 12px;
  overflow-wrap: anywhere;
}
.pre {
  max-height: 320px;
  overflow: auto;
  max-width: 100%;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
  font-size: 12px;
  border: 1px solid var(--border);
  border-radius: 6px;
  padding: 12px;
}
.field {
  display: flex;
  flex-direction: column;
  gap: 4px;
  font-size: 12px;
}
.field textarea {
  min-height: 80px;
  max-height: 200px;
  padding: 8px;
  border: 1px solid var(--border);
  border-radius: 6px;
  background: var(--surface);
}
.field textarea:focus-visible {
  outline: 2px solid var(--ring);
  outline-offset: 2px;
}
.section a,
.actions a,
.row a {
  color: var(--primary);
  text-decoration: underline;
  overflow-wrap: anywhere;
}
@media (pointer: coarse) {
  .actions a,
  .row a {
    min-height: 44px;
    min-width: 44px;
    display: inline-flex;
    align-items: center;
  }
}
@media (max-width: 639px) {
  .search {
    width: 160px;
  }
  .toolbar {
    gap: 4px;
  }
  .main {
    padding: 8px;
  }
}

.boardViewport {
  max-width: 100%;
  overflow-x: auto;
}
.boardViewport [data-board-item] {
  border: 0;
  background: transparent;
}

.navigation {
  display: grid;
  gap: 4px;
}
.navigationLink,
.navigationBrand {
  display: flex;
  align-items: center;
  gap: 8px;
  min-height: 40px;
  padding: 12px;
  white-space: nowrap;
  font-size: 13px;
}
.navigationLink svg {
  flex-shrink: 0;
}
.navigationLink:hover {
  background: var(--surface-hover);
}
.navigationLink:focus-visible {
  outline: 2px solid var(--ring);
  outline-offset: -4px;
}
.navigationLink[aria-current="page"] {
  background: var(--selection);
  color: var(--primary);
}
.navLabel {
  overflow: hidden;
  text-overflow: ellipsis;
}
.filterLabel {
  font-size: 12px;
  color: var(--text-secondary);
}
@container workspace-navigation (max-width:80px) {
  .navLabel {
    display: none;
  }
  .navigationLink,
  .navigationBrand {
    justify-content: center;
  }
}
@media (pointer: coarse) {
  .navigationLink {
    min-height: 44px;
    min-width: 44px;
  }
}
